mapper.select:
SELECT g.windcode AS issuer_code , g.total_score AS inner_issuer_rating FROM ais_inv_analysis.v_inv_grade_result g INNER JOIN ( SELECT windcode , MAX(ts) AS latest_time FROM ais_inv_analysis.v_inv_grade_result WHERE windcode IN
#{code}
GROUP BY windcode ) latest ON latest.windcode = g.windcode AND (g.ts = latest.latest_time OR (g.ts IS NULL AND latest.latest_time IS NULL))

SELECT s.security_code AS issuer_code , MAX(CASE WHEN p.pool_type = 'observe' THEN 1 ELSE 0 END) AS in_observe_pool , MAX(CASE WHEN p.pool_type = 'restricted' THEN 1 ELSE 0 END) AS in_restricted_pool FROM ip_pool_status s INNER JOIN ip_investment_pool p ON p.id = s.target_pool_id AND p.is_deleted = 0 WHERE s.is_deleted = 0 AND s.audit_status = '20' AND s.security_type = 'company' AND p.pool_type IN ('observe', 'restricted') AND s.security_code IN
#{code}
GROUP BY s.security_code

SELECT a.id , a.crmw_scode , a.security_code , a.current_pool_id , a.context_key , a.alert_status FROM ip_crmw_rule_alert a INNER JOIN ( SELECT MAX(id) AS id FROM ip_crmw_rule_alert WHERE is_deleted = 0 AND crmw_scode IN
#{code}
GROUP BY crmw_scode , security_code , current_pool_id ) latest ON latest.id = a.id

mapper.insert:
INSERT INTO ip_crmw_rule_alert (
    crmw_scode
    , crmw_name
    , security_code
    , security_short_name
    , issuer_code
    , issuer_name
    , inner_issuer_rating
    , current_pool_id
    , current_pool_name
    , adjust_log_id
    , fail_reason
    , context_key
    , alert_status
    , last_scan_time
    , deal_user_id
    , deal_user_name
    , deal_time
    , is_deleted
    , crte_time
    , updt_time
) VALUES (
    #{crmwScode}
    , #{crmwName}
    , #{securityCode}
    , #{securityShortName}
    , #{issuerCode}
    , #{issuerName}
    , #{innerIssuerRating}
    , #{currentPoolId}
    , #{currentPoolName}
    , #{adjustLogId}
    , #{failReason}
    , #{contextKey}
    , #{alertStatus}
    , #{lastScanTime}
    , #{dealUserId}
    , #{dealUserName}
    , #{dealTime}
    , #{isDeleted}
    , #{crteTime}
    , #{updtTime}
)

mapper.update:
UPDATE ip_crmw_rule_alert
SET crmw_name = #{crmwName}
    , security_short_name = #{securityShortName}
    , issuer_code = #{issuerCode}
    , issuer_name = #{issuerName}
    , inner_issuer_rating = #{innerIssuerRating}
    , current_pool_name = #{currentPoolName}
    , adjust_log_id = #{adjustLogId}
    , fail_reason = #{failReason}
    , context_key = #{contextKey}
    , last_scan_time = #{lastScanTime}
    , updt_time = #{updtTime}
WHERE id = #{id} AND alert_status = '00' AND is_deleted = 0

UPDATE ip_crmw_rule_alert SET alert_status = '99'
    , updt_time = #{updtTime}
WHERE id = #{id} AND is_deleted = 0 AND alert_status = '00'
